<?php
class AlumnoController {
 public function data(string $page,int $id): array { $m=new Alumno();$d=['perfil'=>$m->perfil($id)]; if($page==='inicio')$d['resumen']=$m->resumen($id); if(in_array($page,['materias','calificaciones']))$d['materias']=$m->materias($id); if($page==='horarios')$d['horarios']=$m->horarios($id);if($page==='asistencias')$d['asistencias']=$m->asistencias($id);if($page==='pagos')$d['pagos']=$m->pagos($id);return $d; }
 public function changePassword(): void { $actual=$_POST['actual']??'';$nueva=$_POST['nueva']??'';$confirmar=$_POST['confirmar']??'';$m=new Alumno();$hash=$m->validarPassword((int)$_SESSION['alumno']['id']);if(!$hash||!password_verify($actual,$hash)){$_SESSION['flash']=['tipo'=>'error','texto'=>'La contraseña actual no coincide.'];}elseif(strlen($nueva)<8||$nueva!==$confirmar){$_SESSION['flash']=['tipo'=>'error','texto'=>'La nueva contraseña debe tener al menos 8 caracteres y coincidir con la confirmación.'];}else{$m->cambiarPassword((int)$_SESSION['alumno']['id'],password_hash($nueva,PASSWORD_DEFAULT));$_SESSION['flash']=['tipo'=>'ok','texto'=>'Contraseña actualizada correctamente.'];}header('Location: index.php?page=cuenta');exit; }
}
